def import_articles():
    conn = sqlite3.connect(DB_PATH)
    count = 0
    for article in ARTICLES:
        title = article["title"]
        content = article["content"]
        # اضافه کردن گره
        conn.execute("INSERT OR IGNORE INTO nodes (type, name, properties) VALUES ('article', ?, ?)",
                     (title, json.dumps({"source": "local_knowledge"})))
        # ایندکس در FTS5
        conn.execute("INSERT OR IGNORE INTO memory_fts (node_id, content) VALUES ((SELECT id FROM nodes WHERE name=?), ?)",
                     (title, content))
        count += 1
    conn.commit()
    conn.close()
    print(f"✔ {count} مقاله به پایگاه دانش سیمرغ اضافه شد.")

if __name__ == "__main__":
    init_db()
    import_articles()
